/// One page of SearchResult results. Nodes() lists them; PageInfo says how to get the next page.
/// Returned by [`Client::search`](crate::Client::search).
#[derive(Debug, Clone, Default, PartialEq, Serialize, Deserialize)]
#[non_exhaustive]
pub struct SearchResultConnection {
    /// How to fetch the next page.
    #[serde(rename = "pageInfo", default, skip_serializing_if = "Option::is_none")]
    pub page_info: Option<PageInfo>,
    /// The items on this page, each wrapped in an edge.
    #[serde(rename = "edges", default, skip_serializing_if = "Option::is_none")]
    pub edges: Option<Vec<SearchResultEdge>>,
}

impl SearchResultConnection {
    /// The SearchResult values on this page, skipping empty edges.
    pub fn nodes(&self) -> impl Iterator<Item = &SearchResult> {
        self.edges.iter().flatten().filter_map(|e| e.node.as_ref())
    }

    /// Consumes the page, returning its SearchResult values.
    pub fn into_nodes(self) -> Vec<SearchResult> {
        self.edges
            .into_iter()
            .flatten()
            .filter_map(|e| e.node)
            .collect()
    }

    /// The cursor for the next page, or `None` on the last page.
    pub fn next_cursor(&self) -> Option<&str> {
        let info = self.page_info.as_ref()?;
        if info.has_next_page != Some(true) {
            return None;
        }
        info.end_cursor.as_deref()
    }
}

